import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 문서번호는 접두어-연도-일련번호(6자리) 형식으로 자동 번호를 매긴다.
const NUMBER_PREFIX = 'AP';
// 가정: 연동 상신 직후 결재 상태는 결재대기다.
const SUBMITTED_STATUS = '결재대기';
const APPROVAL_STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];

function isId(v: unknown): boolean {
  const okType = typeof v === 'number' || (typeof v === 'string' && v.trim() !== '');
  return okType && Number.isInteger(Number(v)) && Number(v) > 0;
}

function isText(v: unknown, max: number): boolean {
  return typeof v === 'string' && v.trim() !== '' && v.length <= max;
}

@Controller('api/v1')
export class FnSir00202Controller {
  @Post('/approval-documents/linked-submissions')
  @HttpCode(200)
  async submitLinkedApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    if (!isId(data['approvalFormId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연동결재 양식을 선택해 주세요.');
    }
    if (!isText(data['title'], 500)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 제목을 500자 이내로 입력해 주세요.');
    }
    if (!isText(data['linkedBusinessType'], 50)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연동 업무 유형을 50자 이내로 입력해 주세요.');
    }
    if (!isId(data['linkedBusinessId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연동 업무 문서 ID를 숫자로 입력해 주세요.');
    }
    const body = typeof data['body'] === 'string' ? data['body'] : null;
    const isUrgent = data['isUrgent'] === true;
    const isSecret = data['isSecret'] === true;
    return transaction(async (db) => {
      const forms = await db.query(
        'SELECT is_linked_approval AS "isLinked" FROM approval_form WHERE approval_form_id = CAST(:formId AS bigint)',
        { formId: data['approvalFormId'] },
      );
      if (forms.length === 0) {
        throw new ApiError(404, 'APPROVAL_FORM_NOT_FOUND', '전자결재 양식을 찾을 수 없습니다.');
      }
      if (forms[0]['isLinked'] !== true) {
        throw new ApiError(422, 'NOT_LINKED_APPROVAL_FORM', '연동결재 대상 양식이 아닙니다.');
      }
      const emps = await db.query(
        'SELECT department_id AS "departmentId" FROM employee WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      if (emps.length === 0 || emps[0]['departmentId'] === null) {
        throw new ApiError(502, 'APPROVAL_SUBMIT_FAILED', '기안 부서를 확인할 수 없어 상신하지 못했습니다.');
      }
      const rows = await db.query(
        `INSERT INTO approval_document (
           approval_form_id, drafter_id, drafter_department_id, document_number,
           title, body, approval_status, is_urgent, is_secret,
           linked_business_type, linked_business_id, submitted_at, created_at, updated_at
         )
         VALUES (
           CAST(:formId AS bigint), CAST(:userId AS bigint), CAST(:deptId AS bigint),
           (SELECT CAST(:prefix AS text) || '-' || to_char(now(), 'YYYY') || '-'
             || lpad(CAST(COALESCE(MAX(approval_document_id), 0) + 1 AS text), 6, '0')
             FROM approval_document),
           :title, :body, :status, :urgent, :secret,
           :bizType, CAST(:bizId AS bigint), now(), now(), now()
         )
         RETURNING approval_document_id AS "approvalDocumentId", approval_status AS "approvalStatus"`,
        {
          formId: data['approvalFormId'],
          userId: user.id,
          deptId: emps[0]['departmentId'],
          prefix: NUMBER_PREFIX,
          title: data['title'],
          body,
          status: SUBMITTED_STATUS,
          urgent: isUrgent,
          secret: isSecret,
          bizType: data['linkedBusinessType'],
          bizId: data['linkedBusinessId'],
        },
      );
      return rows[0];
    });
  }

  @Post('/approval-documents/:approvalDocumentId/apply-result')
  @HttpCode(200)
  async applyApprovalResult(@Req() req: Request) {
    const user = currentUser(req);
    user.require('로그인 사용자');
    const data = checks.inputOf(req.body);
    const documentId = req.params['approvalDocumentId'];
    if (!isId(documentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서 ID가 올바르지 않습니다.');
    }
    const status = data['approvalStatus'];
    if (typeof status !== 'string' || status.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재 진행 상태를 입력해 주세요.');
    }
    if (!APPROVAL_STATUSES.includes(status)) {
      throw new ApiError(422, 'INVALID_APPROVAL_STATUS', '허용되지 않은 결재 상태 값입니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_document_id FROM approval_document WHERE approval_document_id = CAST(:id AS bigint)',
        { id: documentId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재 문서를 찾을 수 없습니다.');
      }
      // 가정: 완료 상태일 때만 완료 일시를 현재 시각으로 기록한다.
      const rows = await db.query(
        `UPDATE approval_document
            SET approval_status = :status,
                completed_at = CASE WHEN CAST(:status AS text) = '완료' THEN now() ELSE completed_at END,
                updated_at = now()
          WHERE approval_document_id = CAST(:id AS bigint)
          RETURNING approval_document_id AS "approvalDocumentId", approval_status AS "approvalStatus"`,
        { id: documentId, status },
      );
      return rows[0];
    });
  }
}

