import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  RefName,
  Select,
  TextInput,
  NumberInput,
  Tiles,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['진행중', '진행중'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['완료', '완료'],
];

export default function FnSir00202Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [mode, setMode] = useState<'' | 'submit' | 'apply'>('');
  const [target, setTarget] = useState<Row | null>(null);
  const [approvalFormId, setApprovalFormId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [linkedBusinessType, setLinkedBusinessType] = useState('');
  const [linkedBusinessId, setLinkedBusinessId] = useState<number | string>('');
  const [newStatus, setNewStatus] = useState('');

  const close = () => {
    setMode('');
    setTarget(null);
  };

  const openSubmit = () => {
    setApprovalFormId('');
    setTitle('');
    setBody('');
    setLinkedBusinessType('');
    setLinkedBusinessId('');
    setMode('submit');
  };

  const openApply = (row: Row) => {
    setTarget(row);
    setNewStatus('');
    setMode('apply');
  };

  const submit = async () => {
    if (approvalFormId === '' || title.trim() === '' || linkedBusinessType.trim() === '' || linkedBusinessId === '') {
      throw new Error('양식, 문서 제목, 연동 업무 유형, 연동 업무 문서 ID를 모두 입력해 주세요.');
    }
    const res = await call('POST', '/approval-documents/linked-submissions', role, {
      approvalFormId,
      title,
      body,
      linkedBusinessType,
      linkedBusinessId,
    });
    setRows([
      {
        approvalDocumentId: res['approvalDocumentId'],
        approvalStatus: res['approvalStatus'],
        approvalFormId,
        title,
        linkedBusinessType,
        linkedBusinessId,
      },
      ...rows,
    ]);
    notify('연동결재를 상신했습니다.');
    close();
  };

  const apply = async () => {
    if (!target) return;
    if (newStatus === '') {
      throw new Error('결재 진행 상태를 선택해 주세요.');
    }
    const res = await call('POST', `/approval-documents/${target['approvalDocumentId']}/apply-result`, role, {
      approvalStatus: newStatus,
    });
    setRows(
      rows.map((r) =>
        r['approvalDocumentId'] === res['approvalDocumentId'] ? { ...r, approvalStatus: res['approvalStatus'] } : r,
      ),
    );
    notify('결재 결과를 반영했습니다.');
    close();
  };

  const waiting = rows.filter((r) => r['approvalStatus'] === '결재대기' || r['approvalStatus'] === '진행중').length;
  const done = rows.filter((r) => r['approvalStatus'] === '승인' || r['approvalStatus'] === '완료').length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['상신 건수', <Num value={rows.length} />],
            ['결재 대기', <Num value={waiting} />],
            ['승인·완료', <Num value={done} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>연동 상신 내역</h2>
        <Band total={rows.length}>
          <button type="button" onClick={openSubmit}>연동결재 상신</button>
        </Band>
        <DataTable
          rows={rows}
          empty="이 화면에서 상신한 문서가 없습니다."
          columns={[
            { key: 'approvalDocumentId', label: '결재문서 ID' },
            { key: 'title', label: '문서 제목' },
            {
              key: 'approvalFormId',
              label: '연동결재 전자결재 양식',
              render: (r) => <RefName table="approval_form" role={role} value={r['approvalFormId']} />,
            },
            { key: 'linkedBusinessType', label: '연동 업무 유형' },
            { key: 'linkedBusinessId', label: '연동 업무 문서 ID' },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r['approvalStatus']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r['approvalStatus'] === '완료' ? null : (
                  <button type="button" onClick={() => openApply(r)}>결과 반영</button>
                ),
            },
          ]}
        />
      </section>
      {mode === 'submit' && (
        <Drawer title="연동결재 상신" onClose={close}>
          <Form onSubmit={submit} submit="상신">
            <Field label="연동결재 전자결재 양식" required>
              <LookupSelect table="approval_form" role={role} value={approvalFormId} onChange={setApprovalFormId} />
            </Field>
            <Field label="문서 제목" required>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="연동 업무 유형" required>
              <TextInput value={linkedBusinessType} onChange={setLinkedBusinessType} />
            </Field>
            <Field label="연동 업무 문서 ID" required>
              <NumberInput value={linkedBusinessId} onChange={setLinkedBusinessId} />
            </Field>
            <Field label="문서 본문" wide>
              <TextInput value={body} onChange={setBody} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'apply' && target && (
        <Drawer title="결재 결과 반영" onClose={close}>
          <Form onSubmit={apply} submit="반영">
            <Field label="결재문서 ID">
              <span>{String(target['approvalDocumentId'])}</span>
            </Field>
            <Field label="결재 진행 상태" required>
              <Select value={newStatus} onChange={setNewStatus} options={STATUS_OPTIONS} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
